[QwFeedbackHandler]
  name = PitaFeedback
  map  = pita_feedback.map
  impl = PITA
  slope_ihwp_in  = 0.2
  slope_ihwp_out = -0.2
  patterns = 200
  log  = ./PITA_Feedback.log

